import React, { useEffect, useState, useCallback } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from "recharts";
import Navbar from "../components/Navbar";
import axiosClient from "../api/axiosClient";
import { useAuth } from "../context/AuthContext";

const TABS = ["Overview", "Pending Approvals", "Households", "Meter Uploads", "Tariff Plans", "Billing Cycles", "Alerts", "Apartment Settings"];

export default function AdminPanel() {
  const { user } = useAuth();
  const [apartmentId, setApartmentId] = useState(user?.apartmentId || "");
  const [apartments, setApartments] = useState([]);
  const [tab, setTab] = useState("Overview");

  useEffect(() => {
    axiosClient.get("/public/apartments").then((res) => setApartments(res.data)).catch(() => {});
  }, []);

  return (
    <div>
      <Navbar />
      <div className="container" style={{ paddingTop: 32, paddingBottom: 48 }}>
        <div className="dash-header">
          <div>
            <h1 className="page-title">Admin Console</h1>
            <p className="page-subtitle" style={{ marginBottom: 0 }}>Manage resident approvals, households, tariffs, meter readings, billing, and fines.</p>
          </div>
        </div>

        <div className="form-group" style={{ maxWidth: 320 }}>
          <label>Managing Apartment</label>
          <select value={apartmentId} onChange={(e) => setApartmentId(e.target.value)}>
            <option value="">Select apartment</option>
            {apartments.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}
          </select>
        </div>

        <div className="tabs">
          {TABS.map((t) => (
            <div key={t} className={`tab ${tab === t ? "active" : ""}`} onClick={() => setTab(t)}>{t}</div>
          ))}
        </div>

        {!apartmentId ? (
          <p style={{ color: "#4b5f63" }}>Select or create an apartment to continue.</p>
        ) : (
          <>
            {tab === "Overview" && <OverviewTab apartmentId={apartmentId} />}
            {tab === "Pending Approvals" && <PendingApprovalsTab apartmentId={apartmentId} />}
            {tab === "Households" && <HouseholdsTab apartmentId={apartmentId} />}
            {tab === "Meter Uploads" && <MeterUploadTab apartmentId={apartmentId} />}
            {tab === "Tariff Plans" && <TariffTab apartmentId={apartmentId} />}
            {tab === "Billing Cycles" && <BillingTab apartmentId={apartmentId} />}
            {tab === "Alerts" && <AlertsTab apartmentId={apartmentId} />}
            {tab === "Apartment Settings" && (
              <ApartmentSettingsTab
                apartment={apartments.find((a) => String(a.id) === String(apartmentId))}
                onUpdated={(updated) => {
                  setApartments((prev) => prev.map((a) => (a.id === updated.id ? updated : a)));
                }}
                onDeleted={() => {
                  setApartments((prev) => prev.filter((a) => String(a.id) !== String(apartmentId)));
                  setApartmentId("");
                  setTab("Overview");
                }}
              />
            )}
          </>
        )}

        {!apartmentId && <CreateApartmentCard onCreated={(a) => setApartments((prev) => [...prev, a])} />}
      </div>
    </div>
  );
}

function PendingApprovalsTab({ apartmentId }) {
  const [pendingUsers, setPendingUsers] = useState([]);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const loadPending = useCallback(() => {
    axiosClient.get(`/admin/pending-residents/apartment/${apartmentId}`)
      .then((res) => setPendingUsers(res.data))
      .catch(() => {});
  }, [apartmentId]);

  useEffect(() => { loadPending(); }, [loadPending]);

  const approve = async (userId) => {
    setError(""); setMessage("");
    try {
      await axiosClient.put(`/admin/residents/${userId}/approve`);
      setMessage("Resident account approved successfully.");
      loadPending();
    } catch (err) {
      setError(err.response?.data?.message || "Failed to approve resident.");
    }
  };

  const reject = async (userId) => {
    const reason = window.prompt("Enter rejection reason for resident:");
    if (reason === null) return;

    setError(""); setMessage("");
    try {
      await axiosClient.put(`/admin/residents/${userId}/reject`, { reason });
      setMessage("Resident registration request rejected.");
      loadPending();
    } catch (err) {
      setError(err.response?.data?.message || "Failed to reject resident.");
    }
  };

  return (
    <div className="card">
      <h3 style={{ marginBottom: 16 }}>Pending Resident Registrations ({pendingUsers.length})</h3>
      {message && <div className="success-banner">{message}</div>}
      {error && <div className="alert-banner">{error}</div>}

      {pendingUsers.length === 0 ? (
        <p style={{ color: "#4b5f63", fontSize: 14 }}>No pending resident authorization requests.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Full Name</th>
              <th>Username</th>
              <th>Email</th>
              <th>Flat Number</th>
              <th>Registered At</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {pendingUsers.map((u) => (
              <tr key={u.id}>
                <td><strong>{u.fullName}</strong></td>
                <td>{u.username}</td>
                <td>{u.email}</td>
                <td><span className="badge badge-info">Flat {u.household?.flatNumber || "N/A"}</span></td>
                <td>{u.createdAt ? new Date(u.createdAt).toLocaleDateString() : "-"}</td>
                <td style={{ display: "flex", gap: 8 }}>
                  <button className="btn btn-primary btn-sm" onClick={() => approve(u.id)}>Approve</button>
                  <button className="btn btn-sm" style={{ background: "var(--danger)", color: "#fff" }} onClick={() => reject(u.id)}>Reject</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function HouseholdsTab({ apartmentId }) {
  const [households, setHouseholds] = useState([]);
  const [form, setForm] = useState({ flatNumber: "", flatSizeSqft: "", occupancy: "", meterSerialNumber: "" });
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const [selectedHousehold, setSelectedHousehold] = useState(null);
  const [fineAmount, setFineAmount] = useState("");
  const [fineReason, setFineReason] = useState("");
  const [fineSaving, setFineSaving] = useState(false);

  const load = useCallback(() => {
    axiosClient.get(`/admin/apartments/${apartmentId}/households`).then((r) => setHouseholds(r.data)).catch(() => {});
  }, [apartmentId]);

  useEffect(() => { load(); }, [load]);

  const submit = async (e) => {
    e.preventDefault();
    setError(""); setMessage("");
    try {
      await axiosClient.post("/admin/households", {
        apartmentId, ...form,
        flatSizeSqft: Number(form.flatSizeSqft),
        occupancy: Number(form.occupancy),
      });
      setMessage("Household registered.");
      setForm({ flatNumber: "", flatSizeSqft: "", occupancy: "", meterSerialNumber: "" });
      load();
    } catch (err) {
      setError(err.response?.data?.message || "Could not register household.");
    }
  };

  const openFineModal = (household) => {
    setSelectedHousehold(household);
    setFineAmount("");
    setFineReason("");
  };

  const submitFine = async (e) => {
    e.preventDefault();
    if (!selectedHousehold) return;

    setFineSaving(true);
    setError(""); setMessage("");

    try {
      const invRes = await axiosClient.get(`/resident/households/${selectedHousehold.id}/invoices`);
      const invoices = invRes.data;

      if (!invoices || invoices.length === 0) {
        alert("No active or finalized invoice found for this household to apply a fine.");
        setFineSaving(false);
        return;
      }

      const latestInvoice = invoices[0];

      await axiosClient.post(`/admin/invoices/${latestInvoice.id}/impose-fine`, {
        fineAmount: Number(fineAmount),
        fineReason: fineReason
      });

      setMessage(`Fine of Rs. ${fineAmount} imposed on Flat ${selectedHousehold.flatNumber}. Email notice sent.`);
      setSelectedHousehold(null);
      load();
    } catch (err) {
      setError(err.response?.data?.message || "Failed to impose fine.");
    } finally {
      setFineSaving(false);
    }
  };

  return (
    <div className="grid grid-2">
      <div className="card">
        <h3 style={{ marginBottom: 16 }}>Register Household</h3>
        {message && <div className="success-banner">{message}</div>}
        {error && <div className="alert-banner">{error}</div>}
        <form onSubmit={submit}>
          <div className="form-group"><label>Flat Number</label>
            <input value={form.flatNumber} onChange={(e) => setForm({ ...form, flatNumber: e.target.value })} required /></div>
          <div className="form-group"><label>Flat Size (sqft)</label>
            <input type="number" value={form.flatSizeSqft} onChange={(e) => setForm({ ...form, flatSizeSqft: e.target.value })} required /></div>
          <div className="form-group"><label>Occupancy</label>
            <input type="number" value={form.occupancy} onChange={(e) => setForm({ ...form, occupancy: e.target.value })} required /></div>
          <div className="form-group"><label>Meter Serial Number (optional)</label>
            <input value={form.meterSerialNumber} onChange={(e) => setForm({ ...form, meterSerialNumber: e.target.value })} /></div>
          <button className="btn btn-primary btn-block">Register Household</button>
        </form>
      </div>

      <div className="card">
        <h3 style={{ marginBottom: 16 }}>Households & Residents ({households.length})</h3>
        <table>
          <thead><tr><th>Flat</th><th>Size</th><th>Residents</th><th>Meter</th><th>Action</th></tr></thead>
          <tbody>
            {households.map((h) => (
              <tr key={h.id}>
                <td><strong>Flat {h.flatNumber}</strong></td>
                <td>{h.flatSizeSqft} sqft</td>
                <td>
                  {h.residents && h.residents.length > 0 ? (
                    h.residents.map((r) => <div key={r.id} style={{ fontSize: 12 }}>• {r.fullName} ({r.email})</div>)
                  ) : (
                    <span style={{ color: "#a0aec0", fontSize: 12 }}>No residents</span>
                  )}
                </td>
                <td>{h.meterActive ? <span className="badge badge-success">Active</span> : <span className="badge badge-danger">Inactive</span>}</td>
                <td>
                  <button className="btn btn-sm" style={{ background: "var(--warning)", color: "#1a202c" }} onClick={() => openFineModal(h)}>
                    Fine
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {selectedHousehold && (
          <div style={{
            position: "fixed", top: 0, left: 0, right: 0, bottom: 0,
            background: "rgba(0,0,0,0.5)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 999
          }}>
            <div className="card" style={{ width: 400, background: "#fff" }}>
              <h3>Impose Fine - Flat {selectedHousehold.flatNumber}</h3>
              <p style={{ fontSize: 13, color: "#4a5568", marginBottom: 16 }}>
                Imposing a fine will adjust the household's current invoice and send an email notification.
              </p>
              <form onSubmit={submitFine}>
                <div className="form-group">
                  <label>Fine Amount (Rs.)</label>
                  <input type="number" step="0.01" value={fineAmount} onChange={(e) => setFineAmount(e.target.value)} required placeholder="e.g. 500" />
                </div>
                <div className="form-group">
                  <label>Reason for Fine</label>
                  <input type="text" value={fineReason} onChange={(e) => setFineReason(e.target.value)} required placeholder="e.g. Unresolved Water Leak Penalty" />
                </div>
                <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
                  <button type="submit" className="btn btn-primary" disabled={fineSaving}>
                    {fineSaving ? "Processing..." : "Confirm Fine"}
                  </button>
                  <button type="button" className="btn btn-outline" onClick={() => setSelectedHousehold(null)}>
                    Cancel
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

